candidates.expr:
constants.edges.filter(m, board[m.source] * side > 0
).filter(m, board[m.target] == 0
).filter(m, forced < 0 || (m.source == forced && m.jump)
).filter(m,
  (board[m.source] == 2 || board[m.source] == -2 ||
    m.dr == (m.jump ? -2 * side : -side)) &&
  (!m.jump || board[m.middle] * side < 0)
)

select.result:
{"board": state.board, "turn": state.turn, "forced": state.forced,
"winner": state.winner, "draw": state.draw, "quiet": state.quiet,
"receipt": state.receipt, "selected": state.selected == action.index ? -1 : action.index}

move.result:
{"board": board, "turn": nextTurn, "forced": forced, "selected": continuing ? action.target : -1,
"winner": won ? -nextTurn : 0, "draw": !won && quiet >= 80,
"quiet": quiet, "receipt": coordinate(action.source) + " → " + coordinate(action.target) + (chosen.jump ? " · captured a piece" : "") + (promoted ? " · crowned king" : "") + (continuing ? " · continue jumping" : "")}

